package com.alkamel.onecash;

import android.app.*;
import android.os.*;
import android.content.*;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.io.*;

public class MainActivity extends Activity {
    Db db; LinearLayout root,body;
    static final int REQ_BACKUP=9001,REQ_RESTORE=9002;
    @Override public void onCreate(Bundle b){super.onCreate(b);db=new Db(this);requestPerms();showHome();}
    void requestPerms(){if(Build.VERSION.SDK_INT>=23){String[] p={android.Manifest.permission.RECEIVE_SMS,android.Manifest.permission.READ_SMS,android.Manifest.permission.SEND_SMS};List<String> missing=new ArrayList<>();for(String x:p)if(checkSelfPermission(x)!=0)missing.add(x);if(!missing.isEmpty())requestPermissions(missing.toArray(new String[0]),12);}}
    TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setPadding(12,10,12,10);t.setTextColor(0xff172b3a);return t;}
    Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->r.run());return b;}
    void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(12,12,12,12);root.setBackgroundColor(0xfff4f6fa);TextView h=text(title,22);h.setTextColor(0xff153b63);root.addView(h);ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setOrientation(0);nav.addView(button("الرئيسية",()->showHome()));nav.addView(button("العملاء",()->showCustomers()));nav.addView(button("المخزون",()->showInventory()));nav.addView(button("الحوالات",()->showTransfers()));nav.addView(button("الإعدادات",()->showSettings()));root.addView(nav);setContentView(root);}
    void showHome(){base("الكامل — أتمتة ون كاش");body.addView(text("إجمالي الحوالات: "+db.countTransfers(),18));body.addView(text("تم إرسالها: "+db.sentCount(),18));body.addView(text("تحتاج متابعة: "+db.reviewCount(),18));body.addView(text("مخزون الكروت",18));for(int n:new int[]{100,200,250,500})body.addView(text(n+" ريال: "+db.available(n)+" كرت",16));body.addView(text("الإرسال الآلي: "+(db.setting("auto_send").equals("1")?"مفعّل":"متوقف"),16));body.addView(button("إضافة عميل",()->showCustomers()));body.addView(button("استيراد كروت",()->showInventory()));body.addView(button("إعداد مراقبة الرسائل",()->showSettings()));body.addView(button("عرض الحوالات",()->showTransfers()));}
    void showCustomers(){base("إدارة العملاء");EditText name=new EditText(this);name.setHint("اسم المحوّل كما يظهر في ون كاش");EditText phone=new EditText(this);phone.setHint("رقم الجوال المستلم");phone.setInputType(3);body.addView(name);body.addView(phone);body.addView(button("حفظ عميل جديد",()->{if(db.addCustomer(name.getText().toString(),phone.getText().toString())){toast("تم حفظ العميل");showCustomers();}else toast("تعذر الحفظ: الاسم مكرر أو البيانات ناقصة");}));body.addView(text("اضغط على العميل لتعديل الاسم أو الرقم، واضغط مطولًا لحذف الربط.",14));for(String[] c:db.customers()){TextView row=text(c[0]+" — "+c[1],16);row.setBackgroundColor(0xffffffff);row.setOnClickListener(v->editCustomer(c[0],c[1]));row.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle("حذف الربط؟").setMessage("سيتم حذف ربط الاسم بالرقم، ولا تُحذف سجلات الحوالات.").setPositiveButton("حذف",(a,b)->{db.deleteCustomer(c[0]);showCustomers();}).setNegativeButton("إلغاء",null).show();return true;});body.addView(row);}}
    void editCustomer(String oldName,String oldPhone){EditText n=new EditText(this);n.setText(oldName);EditText p=new EditText(this);p.setText(oldPhone);p.setInputType(3);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.addView(n);l.addView(p);new AlertDialog.Builder(this).setTitle("تعديل بيانات العميل").setView(l).setPositiveButton("حفظ",(d,w)->{if(db.updateCustomer(oldName,n.getText().toString(),p.getText().toString())){toast("تم التعديل");showCustomers();}else toast("تعذر التعديل — ربما الاسم مكرر");}).setNegativeButton("إلغاء",null).show();}
    void showInventory(){base("مخزون الكروت");for(int n:new int[]{100,200,250,500}){body.addView(text(n+" ريال — المتوفر "+db.available(n),18));body.addView(button("استيراد TXT لفئة "+n,()->pickFile(n)));}body.addView(text("كل سطر في TXT يمثل كرتًا واحدًا. السطور الفارغة تُتجاهل، والكرت المكرر لا يُضاف.",14));}
    void pickFile(int denomination){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("text/plain");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,denomination);}
    void showTransfers(){base("سجل الحوالات");body.addView(button("إعادة مطابقة أسماء الحوالات المراجعة",()->{for(String[] t:db.pendingTransfers()){if(t[3]==null||t[3].trim().isEmpty()){String phone=db.customerPhone(t[1]);if(phone!=null)db.resolveTransferPhone(t[0],phone);}}toast("تم تحديث المطابقة");showTransfers();}));List<String[]> pending=db.pendingTransfers();body.addView(text("الحوالات التي تحتاج معالجة: "+pending.size(),18));for(String[] p:pending){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setBackgroundColor(0xffffffff);card.addView(text(p[1]+" • "+p[2]+" ريال • "+p[4],16));card.addView(text("رقم المستلم: "+(p[3]==null?"غير مرتبط":p[3]),14));if(p[3]!=null&&!p[3].trim().isEmpty())card.addView(button("إرسال الكرت يدويًا",()->manualSend(p[0],p[1],Integer.parseInt(p[2]),p[3])));else card.addView(text("سجّل الاسم والرقم في العملاء ثم أعد المطابقة.",14));body.addView(card);}
        body.addView(text("آخر العمليات",18));for(String s:db.recentTransfers())body.addView(text(s,15));}
    void manualSend(String fp,String payer,int amount,String phone){new AlertDialog.Builder(this).setTitle("تأكيد إرسال الكرت").setMessage("الاسم: "+payer+"\nالمبلغ: "+amount+"\nإلى: "+phone+"\nهل تريد سحب كرت وإرساله؟").setPositiveButton("إرسال",(d,w)->{long card=db.reserveCard(amount);if(card<0){toast("لا يوجد مخزون لهذه الفئة");return;}String code=db.cardCode(card);if(code==null){db.cardState(card,"AVAILABLE");toast("تعذر قراءة الكرت");return;}db.attachCardToTransfer(fp,card);Intent sentIntent=new Intent(this,SmsSentReceiver.class).setAction("com.alkamel.onecash.SMS_SENT").putExtra("fp",fp).putExtra("card",card);PendingIntent sent=PendingIntent.getBroadcast(this,fp.hashCode(),sentIntent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);try{android.telephony.SmsManager.getDefault().sendTextMessage(phone,null,"حوالتك وصلت. كرت "+amount+" ريال: "+code+" - الكامل",sent,null);toast("تم بدء إرسال SMS");}catch(Exception e){db.cardState(card,"AVAILABLE");db.updateTransfer(fp,"FAILED","فشل الإرسال: "+e.getMessage());toast("فشل الإرسال");}showTransfers();}).setNegativeButton("إلغاء",null).show();}
    void showSettings(){base("الإعدادات");EditText sender=new EditText(this);sender.setHint("عنوان/رقم مرسل ون كاش كما يظهر في SMS");sender.setText(db.setting("wallet_sender"));body.addView(sender);body.addView(button("حفظ مرسل ون كاش",()->{db.setSetting("wallet_sender",sender.getText().toString().trim());toast("تم حفظ المرسل");}));Switch sw=new Switch(this);sw.setText("تفعيل الإرسال التلقائي");sw.setChecked(db.setting("auto_send").equals("1"));body.addView(sw);body.addView(button("حفظ إعداد الإرسال",()->{if(sw.isChecked())new AlertDialog.Builder(this).setTitle("تنبيه قبل التفعيل").setMessage("تأكد من مرسل ون كاش، وأسماء العملاء، ومخزون الكروت، واختبر أولًا.").setPositiveButton("تفعيل",(a,b)->{db.setSetting("auto_send","1");toast("الإرسال الآلي مفعّل");showSettings();}).setNegativeButton("إلغاء",null).show();else{db.setSetting("auto_send","0");toast("الإرسال الآلي متوقف");showSettings();}}));body.addView(text("لا تُعالج الرسائل إلا من المرسل المحدد. الاسم غير المسجل، المبلغ غير المدعوم، أو عدم توفر مخزون يمنع الإرسال.",14));body.addView(button("نسخ احتياطي لقاعدة البيانات",()->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"alkamel-onecash-backup.db"),REQ_BACKUP)));body.addView(button("استعادة نسخة احتياطية",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),REQ_RESTORE)));}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(resultCode!=RESULT_OK||data==null)return;try{Uri u=data.getData();if(requestCode==REQ_BACKUP){db.close();try(InputStream in=new FileInputStream(getDatabasePath("onecash.db"));OutputStream out=getContentResolver().openOutputStream(u)){copy(in,out);}db=new Db(this);toast("تم حفظ النسخة الاحتياطية");showSettings();return;}if(requestCode==REQ_RESTORE){db.close();try(InputStream in=getContentResolver().openInputStream(u);OutputStream out=new FileOutputStream(getDatabasePath("onecash.db"))){copy(in,out);}db=new Db(this);toast("تمت الاستعادة — افتح الشاشة مجددًا");showHome();return;}if(requestCode>=100){InputStream in=getContentResolver().openInputStream(u);BufferedReader r=new BufferedReader(new InputStreamReader(in));List<String> codes=new ArrayList<>();String line;while((line=r.readLine())!=null)codes.add(line.trim());r.close();int n=db.importCards(requestCode,codes);toast("تم استيراد "+n+" كرت");showInventory();}}catch(Exception e){toast("تعذر إكمال العملية: "+e.getMessage());if(db==null)db=new Db(this);}}
    void copy(InputStream in,OutputStream out)throws IOException{byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    @Override protected void onDestroy(){if(db!=null)db.close();super.onDestroy();}
}
